INSERT INTO `events` VALUES (1,'qwx2rzk1p3s8n3oztfs88exw','Doanh nghiệp và người lao động nước ngoài cần biết gì?','doanh-nghiep-va-nguoi-lao-dong-nuoc-ngoai-can-biet-gi','2026-03-24 04:28:04.030000','2026-03-25 06:45:55.199000',NULL,1,1,'vi','14:00 - 15:00','Ho Chi Minh','Với hơn 20 năm kinh nghiệm và mạng lưới đối tác rộng khắp, HR2B là một trong những công ty hàng đầu Việt Nam trong việc cung cấp giải pháp nhân sự chuyên nghiệp và linh hoạt, giúp doanh nghiệp tiết kiệm chi phí, nâng cao hiệu quả và tập trung vào hoạt động cốt lõi.\n\nVới hơn 20 năm kinh nghiệm và mạng lưới đối tác rộng khắp, HR2B là một trong những công ty hàng đầu Việt Nam trong việc cung cấp giải pháp nhân sự chuyên nghiệp và linh hoạt, giúp doanh nghiệp tiết kiệm chi phí, nâng cao hiệu quả và tập trung vào hoạt động cốt lõi.',1,0,'2026-03-28','2026-03-31'),(7,'qwx2rzk1p3s8n3oztfs88exw','Doanh nghiệp và người lao động nước ngoài cần biết gì?','doanh-nghiep-va-nguoi-lao-dong-nuoc-ngoai-can-biet-gi','2026-03-24 04:28:04.030000','2026-03-25 06:45:55.199000','2026-03-25 06:45:55.263000',1,1,'vi','14:00 - 15:00','Ho Chi Minh','Với hơn 20 năm kinh nghiệm và mạng lưới đối tác rộng khắp, HR2B là một trong những công ty hàng đầu Việt Nam trong việc cung cấp giải pháp nhân sự chuyên nghiệp và linh hoạt, giúp doanh nghiệp tiết kiệm chi phí, nâng cao hiệu quả và tập trung vào hoạt động cốt lõi.\n\nVới hơn 20 năm kinh nghiệm và mạng lưới đối tác rộng khắp, HR2B là một trong những công ty hàng đầu Việt Nam trong việc cung cấp giải pháp nhân sự chuyên nghiệp và linh hoạt, giúp doanh nghiệp tiết kiệm chi phí, nâng cao hiệu quả và tập trung vào hoạt động cốt lõi.',1,0,'2026-03-28','2026-03-31');
