": [\"images\", \"files\"], \"pluginOptions\": {\"i18n\": {\"localized\": true}}}, \"video\": {\"type\": \"media\", \"multiple\": false, \"allowedTypes\": [\"files\", \"videos\"], \"pluginOptions\": {\"i18n\": {\"localized\": true}}}, \"active\": {\"type\": \"boolean\", \"default\": true, \"pluginOptions\": {\"i18n\": {\"localized\": true}}}, \"locale\": {\"type\": \"string\", \"private\": false, \"visible\": false, \"writable\": true, \"configurable\": false}, \"category\": {\"type\": \"relation\", \"target\": \"api::category.category\", \"relation\": \"oneToOne\"}, \"event_time\": {\"type\": \"string\", \"pluginOptions\": {\"i18n\": {\"localized\": true}}}, \"description\": {\"type\": \"text\", \"pluginOptions\": {\"i18n\": {\"localized\": true}}}, \"localizations\": {\"type\": \"relation\", \"target\": \"api::event.event\", \"private\": false, \"visible\": false, \"relation\": \"oneToMany\", \"writable\": false, \"joinColumn\": {\"name\": \"document_id\", \"referencedTable\": \"events\", \"referencedColumn\": \"document_id\"}, \"configurable\": false, \"unstable_virtual\": true}, \"event_location\": {\"type\": \"string\", \"pluginOptions\": {\"i18n\": {\"localized\": true}}}, \"event_schedules\": {\"type\": \"relation\", \"target\": \"api::event-schedule.event-schedule\", \"mappedBy\": \"event\", \"relation\": \"oneToMany\"}, \"event_participants\": {\"type\": \"relation\", \"target\": \"api::event-participant.event-participant\", \"mappedBy\": \"event\", \"relation\": \"oneToMany\"}}','2026-03-24 04:28:04.189000',1),(86,'api::event-participant.event-participant','k14t5g3aizsxy7brtrad5w7k','vi','published','{\"id\": 1, \"name\": \"Mr. Tom Vovers\", \"about\": \"Chuyên môn: Quản lý\\nKinh nghiệm: 22 n\", \"event\": {\"locale\": \"vi\", \"documentId\": \"qwx2rzk1p3s8n3oztfs88exw\", \"publishedAt\": null}, \"photo\": null, \"author\": \"Chủ tịch\", \"locale\": \"vi\", \"documentId\": \"k14t5g3aizsxy7brtrad5w7k\", \"description\": \"**Gia nhập HR2B:** 2/2002\\n\\n**Kinh nghiệm: **22 năm\\n\\n**Trình độ**\\n\\n- Thạc sỹ Quản trị kinh doanh (MBA), Đại học Quản trị Henley, 2000\\n- Thạc sỹ Quản trị kinh doanh (MBA), Đại học Quản trị Henley, 2000\\n- Thạc sỹ Quản trị kinh doanh (MBA), Đại học Quản trị Henley, 2000\\n- Thạc sỹ Quản trị kinh doanh (MBA), Đại học Quản trị Henley, 2000\\n- Thạc sỹ Quản trị kinh doanh (MBA), Đại học Quản trị Henley, 2000\\n\\nSau khi tốt nghiệp tại Đại học Adelaide, Nam Úc, tôi làm việc tại BHP Steel, Whyalla trong lĩnh vực quan hệ lao động. Năm 1991, tôi chuyển đến trụ sở của công ty BHP Petrolium tại Melbourne để tích hợp nhân sự cho các doanh nghiệp Mỹ và Anh. Năm 1993, tôi đến thành phố Hồ Chí Minh với tư cách thành viên cho dự án mỏ Đại Hùng. Hai năm sau, tôi chuyển đến làm việc tại BHP Steel ở Rayong, Thái Lan trong vai trò giám đốc dự án cho một xưởng sản xuất thép mới. Năm 1997, tôi quay lại Việt Nam làm việc cho công ty British American Tobacco với vị trí Trưởng phòng Nguồn nhân lực và sau đó là Giám đốc Nguồn nhân lực cho khu vực. Năm 2000, tôi gia nhập KPMG và phụ trách Nguồn nhân lực cho khu vực và sau đó năm 2001 chuyển đến Singapore làm việc cho SAP Markets. Năm 2003, tôi trở lại Việt Nam và thành lập công ty HR2B.\\n\\nSau khi tốt nghiệp tại Đại học Adelaide, Nam Úc, tôi làm việc tại BHP Steel, Whyalla trong lĩnh vực quan hệ lao động. Năm 1991, tôi chuyển đến trụ sở của công ty BHP Petrolium tại Melbourne để tích hợp nhân sự cho các doanh nghiệp Mỹ và Anh. Năm 1993, tôi đến thành phố Hồ Chí Minh với tư cách thành viên cho dự án mỏ Đại Hùng. Hai năm sau, tôi chuyển đến làm việc tại BHP Steel ở Rayong, Thái Lan trong vai trò giám đốc dự án cho một xưởng sản xuất thép mới. Năm 1997, tôi quay lại Việt Nam làm việc cho công ty British American Tobacco với vị trí Trưởng phòng Nguồn nhân lực và sau đó là Giám đốc Nguồn nhân lực cho khu vực. Năm 2000, tôi gia nhập KPMG và phụ trách Nguồn nhân lực cho khu vực và sau đó năm 2001 chuyển đến Singapore làm việc cho SAP Markets. Năm 2003, tôi trở lại Việt Nam và thành lập công ty HR2B.\\n\\nSau khi tốt nghiệp tại Đại học Adelaide, Nam Úc, tôi làm việc tại BHP Steel, Whyalla trong lĩnh vực quan hệ lao động. Năm 1991, tôi chuyển đến trụ sở của công ty BHP Petrolium tại Melbourne để tích hợp nhân sự cho các doanh nghiệp Mỹ và Anh. Năm 1993, tôi đến thành phố Hồ Chí Minh với tư cách thành viên cho dự án mỏ Đại Hùng. Hai năm sau, tôi chuyển đến làm việc tại BHP Steel ở Rayong, Thái Lan trong vai trò giám đốc dự án cho một xưởng sản xuất thép mới. Năm 1997, tôi quay lại Việt Nam làm việc cho công ty British American Tobacco với vị trí Trưởng phòng Nguồn nhân lực và sau đó là Giám đốc Nguồn nhân lực cho khu vực. Năm 2000, tôi gia nhập KPMG và phụ trách Nguồn nhân lực cho khu vực và sau đó năm 2001 chuyển đến Singapore làm việc cho SAP Markets. Năm 2003, tôi trở lại Việt Nam và thành lập công ty HR2B.\\n\\nSau khi tốt nghiệp tại Đại học Adelaide, Nam Úc, tôi làm việc tại BHP Steel, Whyalla trong lĩnh vực quan hệ lao động. Năm 1991, tôi chuyển đến trụ sở của công ty BHP Petrolium tại Melbourne để tích hợp nhân sự cho các doanh nghiệp Mỹ và Anh. Năm 1993, tôi đến thành phố Hồ Chí Minh với tư cách thành viên cho dự án mỏ Đại Hùng. Hai năm sau, tôi chuyển đến làm việc tại BHP Steel ở Rayong, Thái Lan trong vai trò giám đốc dự án cho một xưởng sản xuất thép mới. Năm 1997, tôi quay lại Việt Nam làm việc cho công ty British American Tobacco với vị trí Trưởng phòng Nguồn nhân lực và sau đó là Giám đốc Nguồn nhân lực cho khu vực. Năm 2000, tôi gia nhập KPMG và phụ trách Nguồn nhân lực cho khu vực và sau đó năm 2001 chuyển đến Singapore làm việc cho SAP Markets. Năm 2003, tôi trở lại Việt Nam và thành lập công ty HR2B.\\n\\nSau khi tốt nghiệp tại Đại học Adelaide, Nam Úc, tôi làm việc tại BHP Steel, Whyalla trong lĩnh vực quan hệ lao động. Năm 1991, tôi chuyển đến trụ sở của công ty BHP Petrolium tại Melbourne để tích hợp nhân sự cho các doanh nghiệp Mỹ và Anh. Năm 1993, tôi đến thành phố Hồ Chí Minh với tư cách thành viên cho dự án mỏ Đại Hùng. Hai năm sau, tôi chuyển đến làm việc tại BHP Steel ở Rayong, Thái Lan trong vai trò giám đốc dự án cho một xưởng sản xuất thép mới. Năm 1997, tôi quay lại Việt Nam làm việc cho công ty British American Tobacco với vị trí Trưởng phòng Nguồn nhân lực và sau đó là Giám đốc Nguồn nhân lực cho khu vực. Năm 2000, tôi gia nhập KPMG và phụ trách Nguồn nhân lực cho khu vực và sau đó năm 2001 chuyển đến Singapore làm việc cho SAP Markets. Năm 2003, tôi trở lại Việt Nam và thành lập công ty HR2B.\"}','{\"name\": {\"type\": \"string\", \"pluginOptions\": {\"i18n\": {\"localized\": true}}}, \"about\": {\"type\": \"richtext\", \"pluginOptions\": {\"i18n\": {\"localized\": true}}}, \"event\": {\"type\": \"relation\", \"target\": \"api::event.event\", \"relation\": \"manyToOne\", \"inversedBy\": \"event_participants\"}, \"photo\": {\"type\": \"media\", \"multiple\": false, \"allowedTypes\": [\"images\", \"files\", \"videos\", \"audios\"], \"pluginOptions\": {\"i18n\": {\"localized\": true}}}, \"author\": {\"type\": \"string\", \"pluginOptions\": {\"i18n\": {\"localized\": true}}}, \"locale\": {\"type\": \"string\", \"private\": false, \"visible\": false, \"writable\": true, \"configurable\": false}, \"description\": {\"type\": \"richtext\", \"pluginOptions\": {\"i18n\": {\"localized\": true}}}, \"localizations\": {\"type\": \"relation\", \"target\": \"api::event-participant.event-participant\", \"private\": false, \"visible\": false, \"relation\": \"oneToMany\", \"writable\": false, \"joinColumn\": {\"name\": \"document_id\", \"referencedTable\": \"event_participants\", \"referencedColumn\": \"document_id\"}, \"configurable\": false, \"unstable_virtual\": true}}','2026-03-24 04:31:55.845000',1),(87,'api::event-participant.event-participant','k14t5g3aizsxy7brtrad5w7k','vi','published','{\"id\": 1, \"name\": \"Mr. Tom Vovers\", \"about\": \"Chuyên môn: Quản lý\\nKinh nghiệm: 22 n\", \"event\": {\"locale\": \"vi\", \"documentId\": \"qwx2rzk1p3s8n3oztfs88exw\", \"publis